INSERT INTO stabilis_attonbitus_525 (minima, adimpleo_recusandae, beneficium, capillus_termes, quia, bis_allatus_acervus, paens_derideo, sunt_stultus, certus_ager, conspergo, harum, sortitus) VALUES (false, ARRAY[90,61,56], 70664.93, true, NULL, 55018.02, ARRAY['tot','deludo','apostolus'], ARRAY['audeo','dolor','demonstro'], 'Clam adipiscor conatus apparatus agnosco aro curo.', 'Ullus curis occaecati vallum convoco substantia peccatus.', '7c:38:8d:24:c1:89', ARRAY['calcar','abbas','quia']);
