INSERT INTO aegrotatio_acies_136 (vociferor_damnatio, bibo_quaerat, adsum_vulgus, animus, vulnus_torrens, aperte_valde, tabella_tenus_absum, approbo_facere_bestia, depopulo_amo_infit, communis, territo_vapulus, caterva_turba, vehemens_repellendus, doloremque_sponte_adhuc, viscus) VALUES ('2025-05-09T15:42:08.192Z', 3554.12, 'Tandem eos carpo utroque deinde vacuus capitulus vehemens.', '2025-11-10T02:42:48.094Z', 31600.14, '772509e0-1357-4d18-aa4a-66d0391d0fa7', '2023-06-09', 'Repellendus ambulo adsum.', '3a321ca8-53d2-40e1-832a-56190aec83f6', '\xfalseDCCFc7C2c7852ACd', ARRAY['desidero','blanditiis','colligo'], 'Coniecto aegrus aveho carpo nam deporto ipsa uredo.', 26291.9, 'Terreo vinco cunabula tyrannus surgo.', '\xfalse5a3C2283eFE1Fd6C');
INSERT INTO aegrotatio_acies_136 (vociferor_damnatio, bibo_quaerat, adsum_vulgus, animus, vulnus_torrens, aperte_valde, tabella_tenus_absum, approbo_facere_bestia, depopulo_amo_infit, communis, territo_vapulus, caterva_turba, vehemens_repellendus, doloremque_sponte_adhuc, viscus) VALUES ('2024-10-28T21:47:58.868Z', 19514.43, 'Statua caries appello sol.', NULL, 99344.31, '6480cb1f-479e-4b64-a290-5994920bee7c', '2023-06-08', 'Absorbeo auxilium aestivus verecundia claustrum antea animadverto.', '5619cdcf-1fd3-4392-90e6-62d28385320c', '\xfalseCbaCB1A6C8B7b660', ARRAY['summisse','temporibus','taedium'], 'Apud absens stipes candidus.', 93346.91, 'Cultura voco tristis libero verto voluptas.', '\xfalse723A0Aeb30b6DCFC');
INSERT INTO aegrotatio_acies_136 (vociferor_damnatio, bibo_quaerat, adsum_vulgus, animus, vulnus_torrens, aperte_valde, tabella_tenus_absum, approbo_facere_bestia, depopulo_amo_infit, communis, territo_vapulus, caterva_turba, vehemens_repellendus, doloremque_sponte_adhuc, viscus) VALUES ('2023-07-08T08:00:59.270Z', 71340.25, 'Sursum enim tutamen eius.', '2023-12-01T09:09:53.930Z', 13769.3, '4f752395-0c46-46ad-bb04-b56e6c806701', '2024-06-22', 'Teres fugiat cedo nisi coaegresco conventus calculus.', '6cf7e235-d9b0-419a-8564-db419a60d529', '\xfalse8Ac5eC35CEc10FFd', ARRAY['solium','dolores','consectetur'], 'Defendo aegrotatio molestias terebro ceno copiose adhuc absens minima.', 77852.79, 'Cogo cribro concido conscendo debitis beatus soluta tollo tolero paens.', '\xfalse4EB730CEf3d0cF94');
INSERT INTO aegrotatio_acies_136 (vociferor_damnatio, bibo_quaerat, adsum_vulgus, animus, vulnus_torrens, aperte_valde, tabella_tenus_absum, approbo_facere_bestia, depopulo_amo_infit, communis, territo_vapulus, caterva_turba, vehemens_repellendus, doloremque_sponte_adhuc, viscus) VALUES ('2025-01-04T00:41:20.572Z', 21067.77, 'Dicta confugo adduco antiquus patruus.', NULL, 79428.82, '69ef1570-a2ab-45e6-be68-a01b10d5671d', '2023-04-18', 'Valens desolo adstringo.', 'c5b5fb63-0dbe-439e-996f-32396396c26b', '\xfalse97b363b7FFeDE6CD', ARRAY['substantia','demum','vir'], 'Curto vicinus alioqui canis amissio beatae infit necessitatibus venio incidunt.', 82595.34, 'Tamen corrigo blandior color talis.', '\xfalse0aFfC32672Fc2cF3');
INSERT INTO aegrotatio_acies_136 (vociferor_damnatio, bibo_quaerat, adsum_vulgus, animus, vulnus_torrens, aperte_valde, tabella_tenus_absum, approbo_facere_bestia, depopulo_amo_infit, communis, territo_vapulus, caterva_turba, vehemens_repellendus, doloremque_sponte_adhuc, viscus) VALUES ('2026-02-24T01:50:24.945Z', 96336.47, 'Usque vilitas ars corpus cibo aggredior coaegresco.', '2023-08-29T12:02:40.963Z', 46340.06, 'db7e938b-61e2-462c-920a-d57b52335b42', NULL, 'Volutabrum beneficium distinctio adeo.', 'cd2b3b49-b60b-4c65-9728-2886641f32f8', NULL, ARRAY['abbas','expedita','contabesco'], 'Aequus arca dolores absum atrox valeo.', 57723.32, 'Magni viduo acervus neque.', '\xfalsea2f52bFaFecFD85b');
INSERT INTO aegrotatio_acies_136 (vociferor_damnatio, bibo_quaerat, adsum_vulgus, animus, vulnus_torrens, aperte_valde, tabella_tenus_absum, approbo_facere_bestia, depopulo_amo_infit, communis, territo_vapulus, caterva_turba, vehemens_repellendus, doloremque_sponte_adhuc, viscus) VALUES ('2024-02-23T09:55:09.930Z', 78067.74, 'Ait nostrum vae attero tyrannus curo.', '2024-07-13T20:08:00.954Z', 81747.2, '3a49e1b6-a195-4e00-a67e-e7c86ec4517f', NULL, 'Cupio conspergo assentator vacuus curatio tabella eum sollicito.', 'a43ceb72-11c9-460c-9f57-7c60c93d1ed0', '\xfalse0DdebBd7FaA2B5cC', ARRAY['stabilis','conitor','admoneo'], 'Assentator tamen admoneo argentum patria.', 65898.25, 'Civitas callide nisi iure iste.', '\xfalsefb3aeE599cC0F7d3');
