INSERT INTO aegrotatio_acies_136 (vociferor_damnatio, bibo_quaerat, adsum_vulgus, animus, vulnus_torrens, aperte_valde, tabella_tenus_absum, approbo_facere_bestia, depopulo_amo_infit, communis, territo_vapulus, caterva_turba, vehemens_repellendus, doloremque_sponte_adhuc, viscus) VALUES ('2025-07-07T00:52:53.852Z', 86169.59, 'Stipes ultio aspicio cohibeo.', '2024-06-17T22:29:25.899Z', 11062.21, '03d18311-d9cf-400e-9280-101a68891e5b', '2025-02-21', 'Tutamen aperte commodo votum.', '47982198-b28e-4222-82df-071cc708bfb6', '\xfalseF6fE906aC75404e0', ARRAY['defaeco','vir','utor'], 'Debeo velum totam congregatio nesciunt ipsam odit.', 34527.97, 'Armarium spero vespillo depereo thymbra molestias adstringo consequatur vicissitudo comburo.', '\xfalse7303Ef34969F8CC8');
INSERT INTO aegrotatio_acies_136 (vociferor_damnatio, bibo_quaerat, adsum_vulgus, animus, vulnus_torrens, aperte_valde, tabella_tenus_absum, approbo_facere_bestia, depopulo_amo_infit, communis, territo_vapulus, caterva_turba, vehemens_repellendus, doloremque_sponte_adhuc, viscus) VALUES ('2024-11-01T22:57:51.249Z', NULL, 'Doloremque ocer varietas vel adulatio quaerat valde.', '2023-12-08T07:16:30.748Z', 23191.39, '7c49d7a9-a0fb-4616-86bb-184781c9c8b6', '2025-07-04', 'Officia vinculum vulgus stipes tego vapulus color valetudo autus toties.', '88773439-868a-43bc-9831-587f8253df40', '\xfalse0E8E5ACBC17bf5eC', ARRAY['sto','contigo','trucido'], 'Amicitia stabilis adhaero stillicidium.', 28380.61, 'Soleo abutor sophismata deleniti subvenio.', '\xfalseDfb74aC6C5fdDbe8');
INSERT INTO aegrotatio_acies_136 (vociferor_damnatio, bibo_quaerat, adsum_vulgus, animus, vulnus_torrens, aperte_valde, tabella_tenus_absum, approbo_facere_bestia, depopulo_amo_infit, communis, territo_vapulus, caterva_turba, vehemens_repellendus, doloremque_sponte_adhuc, viscus) VALUES ('2025-06-02T00:39:42.732Z', 76079.17, 'Thesaurus sunt vinitor comis despecto arma nisi temeritas desino.', NULL, 61921.35, '2fe0c2f8-ff62-4d22-931d-e981b1c94b5b', '2024-05-11', 'Virtus maxime cruentus cui corona summopere.', 'f5bd23ed-c6cf-4a51-ba67-44ae1adb3a3f', NULL, ARRAY['ex','explicabo','beatae'], 'Dapifer eligendi terror.', 89975.43, 'Verto stipes cado agnitio conitor censura eveniet truculenter adsuesco considero.', '\xfalse77ffA41adee00e08');
INSERT INTO aegrotatio_acies_136 (vociferor_damnatio, bibo_quaerat, adsum_vulgus, animus, vulnus_torrens, aperte_valde, tabella_tenus_absum, approbo_facere_bestia, depopulo_amo_infit, communis, territo_vapulus, caterva_turba, vehemens_repellendus, doloremque_sponte_adhuc, viscus) VALUES ('2023-11-14T04:39:07.180Z', 13573.56, 'Tendo vetus terreo arcus terebro alii accendo.', '2024-10-27T07:41:47.439Z', 33234.42, '7a7fe6f4-9e0a-4b02-a9ad-a1542d493408', '2023-04-04', 'Minus vitae terreo.', '68350a29-ff2f-4df8-b4b5-3bbea7fa8640', '\xfalsef075EaBccB9177d2', ARRAY['auctor','canis','culpa'], 'Voluptate caput temporibus baiulus cohaero utrum assentator vilis corporis.', NULL, 'Cicuta cresco animi tametsi templum celebrer.', '\xfalse7e5751aC12E72AB0');
