INSERT INTO vulnus_tantillus_645 (addo, cornu, vesco, tamisium, id_et_aqua, bellicus_sono_aeternus, patruus_astrum, super_vacuus) VALUES ('{"key":"tutamen","value":15}', -4316, '2023-04-07', NULL, 'Creo distinctio sponte causa acceptus vomer fugit doloremque solio.', 3619.47, '\xfalse93Cd8bC6942360f8', 'Sono contigo sit alioqui atqui sodalitas certus.');
INSERT INTO vulnus_tantillus_645 (addo, cornu, vesco, tamisium, id_et_aqua, bellicus_sono_aeternus, patruus_astrum, super_vacuus) VALUES ('{"key":"quas","value":25}', 7624, '2023-07-21', 'c3:74:c5:67:4f:8c', 'Coniecto casus taedium terror cenaculum coniuratio dolorem totus vesco acies.', 36927.55, '\xfalsea1c8dee7dfC0CF40', 'Viscus advoco doloremque causa comedo denuo.');
