INSERT INTO sulum_spiculum_25 (sortitus, volutabrum_abstergo_qui, textus_ait, solum, aegrus, cubicularis_acquiro, uberrime_decet, aeneus_auditor_tepidus, angelus) VALUES (-2195, '2025-03-22', -970888, '2024-05-21T15:40:38.046Z', 57794.61, '2023-05-06T16:47:31.843Z', 'Deprecator quae pax quisquam considero deleo crur natus ocer.', '66.202.145.38/24', '85:2d:45:64:57:73');
INSERT INTO sulum_spiculum_25 (sortitus, volutabrum_abstergo_qui, textus_ait, solum, aegrus, cubicularis_acquiro, uberrime_decet, aeneus_auditor_tepidus, angelus) VALUES (-9372, '2023-12-02', 19129, '2024-12-08T15:45:39.076Z', 52043.07, '2024-03-20T17:22:17.429Z', 'Amoveo curso ascisco tergum cavus deinde ventosus turba viridis voluptatem.', 'b369:ba48:60df:5f7b:ce7b:4dd5:8ffd:d19f/24', 'b9:a6:43:ec:62:e0');
INSERT INTO sulum_spiculum_25 (sortitus, volutabrum_abstergo_qui, textus_ait, solum, aegrus, cubicularis_acquiro, uberrime_decet, aeneus_auditor_tepidus, angelus) VALUES (-9545, '2025-12-18', 22094, '2025-04-21T22:21:31.686Z', 51346.36, '2024-05-23T20:13:21.588Z', 'Denego exercitationem velociter alter esse adulescens.', '118.228.103.58/24', '16:51:fa:ab:12:a2');
INSERT INTO sulum_spiculum_25 (sortitus, volutabrum_abstergo_qui, textus_ait, solum, aegrus, cubicularis_acquiro, uberrime_decet, aeneus_auditor_tepidus, angelus) VALUES (1022, '2025-05-15', 787518, '2024-06-20T08:44:54.376Z', 63395.74, '2024-11-08T23:31:25.694Z', 'Defendo conscendo ascit pecto colligo creta.', '814c:d486:aa7f:06f8:7bda:49ad:dfbd:8dbc/24', 'eb:6b:5c:5d:fe:7f');
INSERT INTO sulum_spiculum_25 (sortitus, volutabrum_abstergo_qui, textus_ait, solum, aegrus, cubicularis_acquiro, uberrime_decet, aeneus_auditor_tepidus, angelus) VALUES (-8464, '2024-11-15', -334678, '2026-02-23T05:05:34.971Z', NULL, '2023-09-13T08:41:20.622Z', 'Ars arx derelinquo claustrum comprehendo stabilis cognomen usitas crudelis.', '131.173.174.89/24', '02:1f:ab:a3:85:91');
INSERT INTO sulum_spiculum_25 (sortitus, volutabrum_abstergo_qui, textus_ait, solum, aegrus, cubicularis_acquiro, uberrime_decet, aeneus_auditor_tepidus, angelus) VALUES (-2540, '2023-09-17', -667441, '2023-03-14T03:24:06.937Z', 11663.09, '2024-02-01T17:57:44.565Z', 'Tergo tenax antepono nesciunt altus copia stips.', 'b0de:a1b5:8fec:67ea:d775:0fbd:d7cb:ab19/24', '3b:bc:ba:76:64:7e');
INSERT INTO sulum_spiculum_25 (sortitus, volutabrum_abstergo_qui, textus_ait, solum, aegrus, cubicularis_acquiro, uberrime_decet, aeneus_auditor_tepidus, angelus) VALUES (8550, '2025-03-06', -234792, '2023-07-31T03:02:04.565Z', 88788.83, '2024-04-08T09:39:21.228Z', 'Venio decet ratione harum speculum.', 'eae6:bddb:c48f:5e8f:a6fd:c822:f85f:fb9e/24', NULL);
INSERT INTO sulum_spiculum_25 (sortitus, volutabrum_abstergo_qui, textus_ait, solum, aegrus, cubicularis_acquiro, uberrime_decet, aeneus_auditor_tepidus, angelus) VALUES (-9080, '2025-04-27', 743345, '2023-07-11T10:20:26.012Z', 37928.01, '2025-10-27T14:06:57.818Z', 'Comburo veniam sulum aeneus voro colligo.', '60.131.239.28/24', NULL);
INSERT INTO sulum_spiculum_25 (sortitus, volutabrum_abstergo_qui, textus_ait, solum, aegrus, cubicularis_acquiro, uberrime_decet, aeneus_auditor_tepidus, angelus) VALUES (2159, '2023-06-14', 98107, '2024-07-07T11:12:34.039Z', 21355.89, '2024-05-05T14:32:30.248Z', 'Ab vivo arca.', '241.242.219.187/24', 'cf:72:c4:7a:89:be');
INSERT INTO sulum_spiculum_25 (sortitus, volutabrum_abstergo_qui, textus_ait, solum, aegrus, cubicularis_acquiro, uberrime_decet, aeneus_auditor_tepidus, angelus) VALUES (4358, '2025-01-06', 29757, '2024-09-14T07:35:02.886Z', 21639.67, '2026-02-02T04:15:50.275Z', 'Aduro delicate alii ratione degusto carcer copiose.', '197.245.194.21/24', 'f7:be:70:07:76:1b');
INSERT INTO sulum_spiculum_25 (sortitus, volutabrum_abstergo_qui, textus_ait, solum, aegrus, cubicularis_acquiro, uberrime_decet, aeneus_auditor_tepidus, angelus) VALUES (9562, '2026-02-18', 270961, '2025-04-30T23:36:12.464Z', 29041.15, '2023-07-08T19:43:01.906Z', 'Abstergo auxilium tutamen bardus cilicium delectus.', '45.38.97.13/24', '47:ac:7e:b4:72:df');
INSERT INTO sulum_spiculum_25 (sortitus, volutabrum_abstergo_qui, textus_ait, solum, aegrus, cubicularis_acquiro, uberrime_decet, aeneus_auditor_tepidus, angelus) VALUES (9783, '2023-07-23', -808344, '2023-12-10T02:03:07.332Z', 84250.39, '2024-03-29T19:19:48.459Z', 'Conduco deludo fugiat vulpes degenero eos asper quaerat tondeo quidem.', '242.77.235.226/24', NULL);
INSERT INTO sulum_spiculum_25 (sortitus, volutabrum_abstergo_qui, textus_ait, solum, aegrus, cubicularis_acquiro, uberrime_decet, aeneus_auditor_tepidus, angelus) VALUES (NULL, '2024-05-05', -114790, '2025-06-27T14:05:52.647Z', 57051.22, '2023-11-14T19:11:54.249Z', 'Illo sulum claudeo virtus ad absens cenaculum.', 'e3a2:d7ce:7fab:9acf:5f9c:4cc4:358a:3e2d/24', 'b8:27:ab:5a:9f:e2');
INSERT INTO sulum_spiculum_25 (sortitus, volutabrum_abstergo_qui, textus_ait, solum, aegrus, cubicularis_acquiro, uberrime_decet, aeneus_auditor_tepidus, angelus) VALUES (-9762, '2023-04-09', 269746, '2025-04-27T17:30:33.433Z', 37362.12, '2025-04-19T11:21:19.166Z', 'Tricesimus ancilla angelus pauci taceo cicuta est.', '6fad:c8cc:fc40:a8be:a8e2:a116:f4cb:da5f/24', '36:1e:83:80:3f:78');
INSERT INTO sulum_spiculum_25 (sortitus, volutabrum_abstergo_qui, textus_ait, solum, aegrus, cubicularis_acquiro, uberrime_decet, aeneus_auditor_tepidus, angelus) VALUES (129, '2023-03-06', -625549, '2024-11-06T23:30:21.533Z', 33316.97, '2024-11-07T18:56:21.861Z', 'Convoco sublime arguo adiuvo quis tumultus.', '9fae:49e8:5472:cc1a:05ff:f04a:bed3:ccda/24', 'ac:98:4c:29:33:10');
INSERT INTO sulum_spiculum_25 (sortitus, volutabrum_abstergo_qui, textus_ait, solum, aegrus, cubicularis_acquiro, uberrime_decet, aeneus_auditor_tepidus, angelus) VALUES (-3676, '2026-01-13', 349084, '2024-07-10T11:55:22.297Z', 63440.01, '2023-04-24T18:31:47.643Z', 'Ante dolores utrimque sulum sol cunctatio.', 'a9e7:dd6f:b05f:5eba:ccac:8fd2:e268:34ad/24', NULL);
INSERT INTO sulum_spiculum_25 (sortitus, volutabrum_abstergo_qui, textus_ait, solum, aegrus, cubicularis_acquiro, uberrime_decet, aeneus_auditor_tepidus, angelus) VALUES (-4250, '2023-08-25', -45503, '2025-03-08T06:27:08.272Z', 47271.29, '2024-02-29T01:06:54.948Z', 'Creber suasoria ustilo vinum temeritas nihil.', 'b8fc:8bee:dbdd:aedb:de7c:dd98:ed4b:6d08/24', '36:21:9f:8b:85:1a');
INSERT INTO sulum_spiculum_25 (sortitus, volutabrum_abstergo_qui, textus_ait, solum, aegrus, cubicularis_acquiro, uberrime_decet, aeneus_auditor_tepidus, angelus) VALUES (956, '2025-10-11', 210115, '2025-05-25T00:16:48.588Z', 2734.51, '2023-12-05T23:35:25.988Z', 'Argentum thesaurus sint artificiose defendo cum.', '27.122.210.18/24', '66:04:2e:d7:22:aa');
INSERT INTO sulum_spiculum_25 (sortitus, volutabrum_abstergo_qui, textus_ait, solum, aegrus, cubicularis_acquiro, uberrime_decet, aeneus_auditor_tepidus, angelus) VALUES (6878, '2023-09-22', -630869, '2023-11-09T11:15:22.285Z', 13.18, '2023-05-30T15:14:36.833Z', 'Vobis volo angelus suus bardus considero termes vesica tumultus carmen.', '8bcf:afdf:dd4a:d19e:90ff:49f3:23d8:abad/24', 'f6:92:82:f0:80:4e');
INSERT INTO sulum_spiculum_25 (sortitus, volutabrum_abstergo_qui, textus_ait, solum, aegrus, cubicularis_acquiro, uberrime_decet, aeneus_auditor_tepidus, angelus) VALUES (-8329, '2023-11-27', -95506, '2025-03-13T14:38:44.089Z', 53124.21, '2025-12-16T12:28:51.639Z', 'Subnecto vinum spectaculum amaritudo adamo commemoro repellat triumphus.', '249.8.0.121/24', 'af:4d:e4:28:f9:bc');
INSERT INTO sulum_spiculum_25 (sortitus, volutabrum_abstergo_qui, textus_ait, solum, aegrus, cubicularis_acquiro, uberrime_decet, aeneus_auditor_tepidus, angelus) VALUES (-2526, '2023-08-21', 42853, '2024-04-10T15:48:16.471Z', 83599.24, '2025-03-14T06:13:37.751Z', 'Ustulo coruscus theatrum ultra atavus cauda ater sol sol suasoria.', '150.85.14.21/24', '97:57:1b:0b:ae:06');
INSERT INTO sulum_spiculum_25 (sortitus, volutabrum_abstergo_qui, textus_ait, solum, aegrus, cubicularis_acquiro, uberrime_decet, aeneus_auditor_tepidus, angelus) VALUES (3689, '2024-11-21', 450869, '2024-07-16T00:15:58.628Z', 33268.14, '2024-06-15T22:39:13.945Z', 'Cito utrum curvo stipes vindico angulus.', '224.170.72.224/24', '37:d9:f7:f2:bf:f4');
INSERT INTO sulum_spiculum_25 (sortitus, volutabrum_abstergo_qui, textus_ait, solum, aegrus, cubicularis_acquiro, uberrime_decet, aeneus_auditor_tepidus, angelus) VALUES (NULL, '2024-05-17', 569347, '2023-05-31T13:52:52.983Z', 35781.2, '2025-05-06T00:27:22.745Z', 'Super error dolores cilicium.', '215.142.38.42/24', '78:ea:60:e7:42:08');
INSERT INTO sulum_spiculum_25 (sortitus, volutabrum_abstergo_qui, textus_ait, solum, aegrus, cubicularis_acquiro, uberrime_decet, aeneus_auditor_tepidus, angelus) VALUES (3240, '2025-05-02', -934042, '2024-04-04T18:59:27.565Z', 51061.08, '2024-01-24T19:20:04.246Z', 'Clementia textus appositus depromo ascisco acerbitas eveniet aetas.', 'dfd1:3f4c:3b5e:afcc:b6e6:23ca:1b69:9785/24', '7a:ba:e2:8c:f0:44');
INSERT INTO sulum_spiculum_25 (sortitus, volutabrum_abstergo_qui, textus_ait, solum, aegrus, cubicularis_acquiro, uberrime_decet, aeneus_auditor_tepidus, angelus) VALUES (8174, '2024-12-17', 771761, '2026-02-05T11:07:57.651Z', 20938.6, '2023-11-04T09:02:37.805Z', 'Sint traho deputo demergo vespillo damno adflicto amplitudo.', '13.27.57.77/24', '56:55:2c:1b:e9:9b');
INSERT INTO sulum_spiculum_25 (sortitus, volutabrum_abstergo_qui, textus_ait, solum, aegrus, cubicularis_acquiro, uberrime_decet, aeneus_auditor_tepidus, angelus) VALUES (2898, '2024-01-01', -231699, '2025-07-03T09:08:41.524Z', 85482.26, '2023-04-19T18:33:13.329Z', 'Calcar adsidue conduco autem canto.', '125.242.173.214/24', '6c:00:9c:26:52:ee');
INSERT INTO sulum_spiculum_25 (sortitus, volutabrum_abstergo_qui, textus_ait, solum, aegrus, cubicularis_acquiro, uberrime_decet, aeneus_auditor_tepidus, angelus) VALUES (-9045, '2025-07-05', -515739, '2024-05-18T22:33:25.826Z', 98775.06, '2024-10-21T23:19:10.648Z', NULL, '251.49.230.233/24', '66:90:a5:0a:6b:74');
INSERT INTO sulum_spiculum_25 (sortitus, volutabrum_abstergo_qui, textus_ait, solum, aegrus, cubicularis_acquiro, uberrime_decet, aeneus_auditor_tepidus, angelus) VALUES (5344, '2025-05-08', -872743, '2024-01-05T09:25:43.782Z', 28209.19, '2025-05-13T16:06:11.433Z', 'Summisse cenaculum bis curtus virga charisma sed atrocitas ventito suffragium.', '139.67.187.62/24', '6e:09:69:a3:65:ea');
INSERT INTO sulum_spiculum_25 (sortitus, volutabrum_abstergo_qui, textus_ait, solum, aegrus, cubicularis_acquiro, uberrime_decet, aeneus_auditor_tepidus, angelus) VALUES (6259, '2024-12-02', 218609, '2023-08-24T00:51:57.625Z', 77784.2, '2024-08-08T07:10:28.789Z', NULL, 'e7a4:90f0:6ad0:b24c:e475:ca1d:4fce:c26a/24', '4e:76:b5:7a:d1:6a');
INSERT INTO sulum_spiculum_25 (sortitus, volutabrum_abstergo_qui, textus_ait, solum, aegrus, cubicularis_acquiro, uberrime_decet, aeneus_auditor_tepidus, angelus) VALUES (5600, '2025-05-02', -986610, '2024-01-11T14:20:48.882Z', 49748.17, '2025-07-07T02:22:54.285Z', 'Thorax verumtamen crepusculum corona.', '236.233.223.212/24', '4d:64:51:27:04:72');
INSERT INTO sulum_spiculum_25 (sortitus, volutabrum_abstergo_qui, textus_ait, solum, aegrus, cubicularis_acquiro, uberrime_decet, aeneus_auditor_tepidus, angelus) VALUES (9994, '2025-05-02', 46463, '2025-09-09T12:05:47.087Z', 52784.47, '2024-03-20T15:20:23.954Z', 'Tibi ab amoveo tergiversatio defero deleniti tactus.', '23.78.159.104/24', 'd9:fd:2d:cd:ac:82');
INSERT INTO sulum_spiculum_25 (sortitus, volutabrum_abstergo_qui, textus_ait, solum, aegrus, cubicularis_acquiro, uberrime_decet, aeneus_auditor_tepidus, angelus) VALUES (-2616, '2023-10-15', -5856, '2025-07-16T16:14:52.850Z', 69012.51, '2025-10-20T00:05:32.032Z', 'Crux numquam contego.', 'dec7:cf1f:abda:6767:6219:5f5c:bbac:a428/24', '82:34:d6:21:46:b0');
INSERT INTO sulum_spiculum_25 (sortitus, volutabrum_abstergo_qui, textus_ait, solum, aegrus, cubicularis_acquiro, uberrime_decet, aeneus_auditor_tepidus, angelus) VALUES (-2515, '2024-03-11', -261614, '2023-05-22T08:58:56.330Z', NULL, '2024-04-01T04:52:03.645Z', 'Libero curto cedo amplexus.', 'ca1c:a13e:0e47:b5f5:dffb:482f:7bed:aeb9/24', '80:58:4f:b8:c9:c4');
