INSERT INTO aequitas_temporibus_486 (vetus_verbum, quia_dens, centum_amaritudo_conservo, aer_ater, coaegresco_una, natus_triumphus, ventosus) VALUES ('\xfalseA6A274FB26c2deCD', '2024-11-12', '2025-05-15', '2e:48:ed:53:ac:a1', ARRAY['urbanus','utilis','succedo'], 17657.26, 'Amaritudo vomer asporto deputo tibi spiculum cura clamo adversus.');
INSERT INTO aequitas_temporibus_486 (vetus_verbum, quia_dens, centum_amaritudo_conservo, aer_ater, coaegresco_una, natus_triumphus, ventosus) VALUES ('\xfalseE4c9EcCd7eEB4D06', '2024-12-13', '2024-04-26', 'f6:07:59:08:31:b3', ARRAY['spero','aperio','pecco'], 272.09, 'Curto deinde ver celer volutabrum.');
INSERT INTO aequitas_temporibus_486 (vetus_verbum, quia_dens, centum_amaritudo_conservo, aer_ater, coaegresco_una, natus_triumphus, ventosus) VALUES ('\xfalseB7c4814Af49e32f9', '2024-12-27', '2024-10-07', '47:af:39:4b:ac:e5', ARRAY['cupiditate','vinco','absque'], 64581.47, 'Strenuus inventore aeternus cena vulgivagus tamen clibanus cotidie aequitas.');
INSERT INTO aequitas_temporibus_486 (vetus_verbum, quia_dens, centum_amaritudo_conservo, aer_ater, coaegresco_una, natus_triumphus, ventosus) VALUES ('\xfalse1143C27BE26a9Bed', '2023-09-25', '2024-11-04', '36:6d:08:e0:d3:7d', ARRAY['accedo','contego','tabella'], 3973.93, 'Aveho tepesco animadverto maxime spargo facilis.');
INSERT INTO aequitas_temporibus_486 (vetus_verbum, quia_dens, centum_amaritudo_conservo, aer_ater, coaegresco_una, natus_triumphus, ventosus) VALUES ('\xfalseB049679DeFB70bCf', '2024-05-07', '2026-02-07', '98:6d:39:43:c7:fc', ARRAY['vesco','varietas','cogo'], 13388.85, NULL);
INSERT INTO aequitas_temporibus_486 (vetus_verbum, quia_dens, centum_amaritudo_conservo, aer_ater, coaegresco_una, natus_triumphus, ventosus) VALUES ('\xfalseF877BcCB7B858bF9', '2025-09-22', '2023-03-26', 'c4:35:c5:94:1b:1b', ARRAY['canto','desino','viduo'], 39385.44, 'Adulescens magni tamisium artificiose bellicus comburo tabella similique degero.');
INSERT INTO aequitas_temporibus_486 (vetus_verbum, quia_dens, centum_amaritudo_conservo, aer_ater, coaegresco_una, natus_triumphus, ventosus) VALUES ('\xfalse1Fb1A1AF4B2AEEdF', '2025-10-10', '2024-02-07', '75:03:f6:1d:15:16', ARRAY['patrocinor','voluptatibus','tibi'], 83626.11, 'Subseco valde volutabrum tener eligendi nam deprimo arcus perspiciatis.');
