INSERT INTO ducimus_textus_433 (currus_peccatus_adopto, abundans_ab, combibo, alii, amaritudo, appono_clam, uxor_occaecati, tergum_surgo, amo_animus_paens, audax_antea_139_id, stella_deduco) VALUES ('255.243.84.251/24', 60638.87, -931576, 'Armarium vero cur alveus statua tempora cupio cura.', 75965.68, 73512.36, NULL, 'Viriliter vetus suspendo thesaurus cultura.', '2023-09-14T23:28:27.364Z', 11, '94:c2:0d:33:db:b9');
INSERT INTO ducimus_textus_433 (currus_peccatus_adopto, abundans_ab, combibo, alii, amaritudo, appono_clam, uxor_occaecati, tergum_surgo, amo_animus_paens, audax_antea_139_id, stella_deduco) VALUES ('df4f:58ae:8fb6:54fd:492b:ad6a:b3ae:6cd7/24', 77779.38, -61046, 'Tersus adeo tredecim atque.', 31134.8, 72657.09, NULL, 'Vicissitudo curtus spargo odio nesciunt arguo quaerat.', '2023-11-18T07:54:59.274Z', 8, 'cd:cc:2d:5b:90:85');
INSERT INTO ducimus_textus_433 (currus_peccatus_adopto, abundans_ab, combibo, alii, amaritudo, appono_clam, uxor_occaecati, tergum_surgo, amo_animus_paens, audax_antea_139_id, stella_deduco) VALUES ('abc0:d825:e4ab:1d8b:5bbe:8fc3:ddae:7f19/24', NULL, 286968, 'Aiunt animus tenax totam.', 89267.7, 86430.15, '27ee:715e:bd9a:73ed:99fd:d5ac:489c:03f5', 'Aurum accedo libero vulgo terra quas decumbo.', '2024-05-28T02:57:10.084Z', 81, '71:f1:70:eb:51:08');
INSERT INTO ducimus_textus_433 (currus_peccatus_adopto, abundans_ab, combibo, alii, amaritudo, appono_clam, uxor_occaecati, tergum_surgo, amo_animus_paens, audax_antea_139_id, stella_deduco) VALUES ('9535:b9d7:ee3d:d04e:fca7:c5ba:5eca:f1ef/24', 86376.55, NULL, 'Ullam ustulo audacia defaeco aedificium conculco sunt assumenda earum.', 96624.64, 81469.9, '70.75.21.25', 'Corpus solium ager.', '2023-10-14T22:18:40.845Z', 65, '43:d1:96:b1:57:67');
INSERT INTO ducimus_textus_433 (currus_peccatus_adopto, abundans_ab, combibo, alii, amaritudo, appono_clam, uxor_occaecati, tergum_surgo, amo_animus_paens, audax_antea_139_id, stella_deduco) VALUES ('df84:8ba5:fa39:1c0e:e8db:4bd5:afa7:bc4a/24', NULL, 98166, 'Modi ulciscor uterque angustus vae utor deprecator utrum.', 69248.34, 56654.74, '125.159.176.57', 'Ancilla civis creber subseco pecus ab deporto curso.', '2026-01-12T17:14:47.586Z', 54, '8d:f5:f1:1d:07:2d');
INSERT INTO ducimus_textus_433 (currus_peccatus_adopto, abundans_ab, combibo, alii, amaritudo, appono_clam, uxor_occaecati, tergum_surgo, amo_animus_paens, audax_antea_139_id, stella_deduco) VALUES ('fec1:4c71:6ff6:a90d:fa97:0abc:c4ed:e0e6/24', 67064.64, -358992, 'Cunabula ante decretum astrum vulariter denuncio abeo cometes.', 5868.04, 6952.3, '47.105.128.208', 'Thymbra vomito conatus sonitus texo.', '2025-04-21T22:26:28.481Z', 51, '4c:c3:dd:7f:d4:4f');
INSERT INTO ducimus_textus_433 (currus_peccatus_adopto, abundans_ab, combibo, alii, amaritudo, appono_clam, uxor_occaecati, tergum_surgo, amo_animus_paens, audax_antea_139_id, stella_deduco) VALUES ('161.216.212.180/24', 46159.04, 845765, 'Delectatio conturbo dolorem aufero.', 56822.89, 3081.9, '91.72.254.156', 'Accusator veniam enim antiquus depopulo cubicularis comminor.', '2025-10-03T07:21:46.061Z', 29, 'fe:2d:3e:37:52:e7');
INSERT INTO ducimus_textus_433 (currus_peccatus_adopto, abundans_ab, combibo, alii, amaritudo, appono_clam, uxor_occaecati, tergum_surgo, amo_animus_paens, audax_antea_139_id, stella_deduco) VALUES ('4fcc:e5ac:46fc:faf4:c4a8:07bd:5951:9ada/24', 55239.8, -462639, 'Peior conicio cornu cinis temptatio crastinus vitiosus praesentium alius.', 80616.13, 83058.85, '4cf4:dad4:ab0f:70bc:bcf6:82e5:7bd4:da4b', 'Commodi dolorem defero ancilla vere.', '2023-12-11T22:25:48.016Z', 78, '21:a7:c7:f4:ad:7c');
INSERT INTO ducimus_textus_433 (currus_peccatus_adopto, abundans_ab, combibo, alii, amaritudo, appono_clam, uxor_occaecati, tergum_surgo, amo_animus_paens, audax_antea_139_id, stella_deduco) VALUES ('177.98.225.154/24', 74464.65, -459929, 'Vorax communis utique cilicium defluo despecto tripudio textus.', 15181.78, 88465.42, NULL, 'Abutor contra arca vapulus.', '2024-02-04T23:29:27.364Z', 8, 'bf:ce:77:59:a3:77');
INSERT INTO ducimus_textus_433 (currus_peccatus_adopto, abundans_ab, combibo, alii, amaritudo, appono_clam, uxor_occaecati, tergum_surgo, amo_animus_paens, audax_antea_139_id, stella_deduco) VALUES ('53de:fb58:ea03:7cd7:5afc:cda4:c848:cbdc/24', 74157.33, -505710, 'Audax stillicidium coerceo crustulum doloribus adipisci absque ducimus.', 10027.65, 83377.48, '135.17.76.136', 'Civis auxilium patruus patruus communis magni.', '2023-11-05T14:23:04.795Z', 16, '6f:92:d0:1c:c5:8a');
INSERT INTO ducimus_textus_433 (currus_peccatus_adopto, abundans_ab, combibo, alii, amaritudo, appono_clam, uxor_occaecati, tergum_surgo, amo_animus_paens, audax_antea_139_id, stella_deduco) VALUES ('39.97.40.161/24', 19216.03, 234814, 'Stips curto coadunatio bellum.', 98345.49, 24191.95, 'd3e3:c031:a6ac:74da:8c1f:a8d2:b8be:4db1', 'Depraedor similique beatae ante una abbas coepi aequus dedico rerum.', '2024-09-02T04:24:09.389Z', 55, '57:49:68:ac:8c:d6');
INSERT INTO ducimus_textus_433 (currus_peccatus_adopto, abundans_ab, combibo, alii, amaritudo, appono_clam, uxor_occaecati, tergum_surgo, amo_animus_paens, audax_antea_139_id, stella_deduco) VALUES ('62.71.193.83/24', 25310.13, 510354, 'Congregatio strues umquam creptio tricesimus tristis utrimque.', 65020.79, 26586.8, '175.48.145.216', NULL, '2025-06-17T00:12:20.628Z', 10, 'fb:0b:d3:08:cb:41');
INSERT INTO ducimus_textus_433 (currus_peccatus_adopto, abundans_ab, combibo, alii, amaritudo, appono_clam, uxor_occaecati, tergum_surgo, amo_animus_paens, audax_antea_139_id, stella_deduco) VALUES ('cbcb:8d5e:9de1:2bba:cd34:49af:88cf:7847/24', 7586.8, 615444, 'Ventus ter animadverto aeger curis derelinquo correptius.', 74197.35, 26752.34, 'a347:ee56:898e:58e4:ccc9:e7b9:f7da:64d6', 'Urbanus vere aperiam canonicus textor cotidie contabesco auctor.', '2024-11-23T12:59:10.884Z', 60, '2c:28:45:0a:fe:4d');
INSERT INTO ducimus_textus_433 (currus_peccatus_adopto, abundans_ab, combibo, alii, amaritudo, appono_clam, uxor_occaecati, tergum_surgo, amo_animus_paens, audax_antea_139_id, stella_deduco) VALUES ('aeae:19bf:586d:dba9:c1ee:bcbf:ab50:8b84/24', 31916.1, -913435, NULL, 66481.83, 28278.78, 'd2ae:ed21:725b:4fca:1859:88a3:3594:52bb', 'Depromo absum distinctio teres complectus.', '2023-04-21T13:05:55.992Z', 62, 'f9:47:d3:7e:09:97');
INSERT INTO ducimus_textus_433 (currus_peccatus_adopto, abundans_ab, combibo, alii, amaritudo, appono_clam, uxor_occaecati, tergum_surgo, amo_animus_paens, audax_antea_139_id, stella_deduco) VALUES ('207.156.241.134/24', 16036.25, -467840, 'Inventore porro bos conqueror sol comes.', 68238.26, 58188.85, 'af9f:d7d3:d7bb:9f7f:7fe4:08de:42f6:f61b', 'Tamisium sapiente caterva claustrum acsi.', NULL, 55, '21:02:55:aa:01:55');
INSERT INTO ducimus_textus_433 (currus_peccatus_adopto, abundans_ab, combibo, alii, amaritudo, appono_clam, uxor_occaecati, tergum_surgo, amo_animus_paens, audax_antea_139_id, stella_deduco) VALUES ('eea1:d935:9fba:5dba:0fa4:07b9:cfc4:22ae/24', 46904.82, 815978, NULL, 47338.16, 96666.33, '4cba:a8cc:8bc0:38c9:aa8e:3ddf:ac5b:ec4c', 'Quis vulnus audio.', '2023-04-19T02:01:57.913Z', 22, 'bc:8f:90:00:c2:8a');
INSERT INTO ducimus_textus_433 (currus_peccatus_adopto, abundans_ab, combibo, alii, amaritudo, appono_clam, uxor_occaecati, tergum_surgo, amo_animus_paens, audax_antea_139_id, stella_deduco) VALUES ('aca1:d4bf:accc:ce4d:4d84:dd70:688d:2c89/24', 91534.32, -366969, 'Exercitationem damno tot ab deputo cultura coniecto.', 24819.45, 85362.98, NULL, 'Truculenter thesis terreo utilis cum astrum depraedor vaco truculenter ars.', '2023-04-07T03:27:20.128Z', 10, 'e3:81:d0:92:29:ab');
INSERT INTO ducimus_textus_433 (currus_peccatus_adopto, abundans_ab, combibo, alii, amaritudo, appono_clam, uxor_occaecati, tergum_surgo, amo_animus_paens, audax_antea_139_id, stella_deduco) VALUES ('b5c5:a4f7:3bbd:aa2d:05e5:cd37:a8bd:51eb/24', 5131.97, 52711, 'Basium pariatur despecto armarium speciosus conventus angustus.', 84460.83, 91982.07, '211.217.54.64', 'Vergo adicio coepi.', '2024-02-18T22:09:08.056Z', 59, '12:e5:81:af:09:36');
INSERT INTO ducimus_textus_433 (currus_peccatus_adopto, abundans_ab, combibo, alii, amaritudo, appono_clam, uxor_occaecati, tergum_surgo, amo_animus_paens, audax_antea_139_id, stella_deduco) VALUES ('222.148.214.11/24', 54940.32, 329432, 'Desparatus desolo arbitro bellicus asporto beatae tumultus trado crebro.', 35680.08, 13376.72, '5.78.92.62', 'Taceo curtus cinis curis tergo repellendus usus dolores rem.', '2023-07-02T20:06:52.492Z', 74, '64:ee:5c:7f:2f:c8');
INSERT INTO ducimus_textus_433 (currus_peccatus_adopto, abundans_ab, combibo, alii, amaritudo, appono_clam, uxor_occaecati, tergum_surgo, amo_animus_paens, audax_antea_139_id, stella_deduco) VALUES ('7061:7c80:b2bb:c1ae:af82:71e4:ebdc:1040/24', 92731.63, NULL, 'Trado virga advenio amoveo.', 33182.07, 16223.06, '845d:eeb4:0f17:4dfc:eeee:cacb:8601:c70b', 'Cogito cras tersus depraedor vado molestiae.', '2024-06-02T14:07:27.638Z', 29, '52:4e:04:54:95:ce');
INSERT INTO ducimus_textus_433 (currus_peccatus_adopto, abundans_ab, combibo, alii, amaritudo, appono_clam, uxor_occaecati, tergum_surgo, amo_animus_paens, audax_antea_139_id, stella_deduco) VALUES ('4b30:7899:51fc:f9ad:da1a:fa34:d273:aadb/24', 81011.96, -991713, 'Aestas verumtamen video nam demum tergum.', 26707.95, 76301.41, '140.205.203.111', 'Quas demonstro porro vulariter ubi vomer recusandae confero corporis.', '2025-03-17T02:02:15.805Z', 79, '72:aa:84:0a:5b:19');
INSERT INTO ducimus_textus_433 (currus_peccatus_adopto, abundans_ab, combibo, alii, amaritudo, appono_clam, uxor_occaecati, tergum_surgo, amo_animus_paens, audax_antea_139_id, stella_deduco) VALUES ('9.137.19.209/24', 15169.47, 951699, 'Sint caterva natus depopulo.', 90705.89, 5986.51, '249.65.19.108', 'Antea tero validus tabgo minima demens surgo admoveo.', '2024-08-09T13:01:36.745Z', 73, 'b1:a5:89:b6:55:20');
INSERT INTO ducimus_textus_433 (currus_peccatus_adopto, abundans_ab, combibo, alii, amaritudo, appono_clam, uxor_occaecati, tergum_surgo, amo_animus_paens, audax_antea_139_id, stella_deduco) VALUES ('6a3a:aa2b:fb38:1eff:2608:66c2:bede:0313/24', 29094.55, -61914, 'Varius baiulus sophismata iure terror terreo tabesco.', 73690.16, 97536.2, '95.192.160.176', 'Defendo aperte coerceo aspernatur cariosus spiculum.', '2025-10-23T13:16:19.173Z', 26, '47:df:d8:23:60:e4');
INSERT INTO ducimus_textus_433 (currus_peccatus_adopto, abundans_ab, combibo, alii, amaritudo, appono_clam, uxor_occaecati, tergum_surgo, amo_animus_paens, audax_antea_139_id, stella_deduco) VALUES ('20.222.26.56/24', 14514.08, NULL, 'Caelum ambulo sperno.', 43070.47, 36497.75, '72.1.79.14', 'Tempore torqueo calco asporto valeo tendo venustas.', '2025-09-21T18:56:15.962Z', 84, '0a:38:ae:c5:8b:cc');
INSERT INTO ducimus_textus_433 (currus_peccatus_adopto, abundans_ab, combibo, alii, amaritudo, appono_clam, uxor_occaecati, tergum_surgo, amo_animus_paens, audax_antea_139_id, stella_deduco) VALUES ('216.28.116.100/24', 77167.61, 459322, 'Reiciendis animus derideo.', 28209.43, 30349.13, '65cf:ced6:4e8f:d2ae:ae3e:b55d:4594:fafd', 'Ultio unus uterque cicuta optio agnitio.', '2023-08-20T19:19:05.389Z', 94, '81:59:d2:f4:2e:54');
INSERT INTO ducimus_textus_433 (currus_peccatus_adopto, abundans_ab, combibo, alii, amaritudo, appono_clam, uxor_occaecati, tergum_surgo, amo_animus_paens, audax_antea_139_id, stella_deduco) VALUES ('dfc6:60c0:c9ea:bed0:4deb:1256:51fa:c5c3/24', 99972.2, NULL, 'Veritas ipsum illo terror calco tertius adulatio depraedor despecto.', 7123.33, 31762.7, 'cfad:c07a:f839:8dff:70ec:d8fb:e46a:b34d', 'Conicio pecto vulpes libero spargo cito bardus.', '2023-09-19T12:39:55.874Z', 87, 'bb:3d:62:09:19:df');
INSERT INTO ducimus_textus_433 (currus_peccatus_adopto, abundans_ab, combibo, alii, amaritudo, appono_clam, uxor_occaecati, tergum_surgo, amo_animus_paens, audax_antea_139_id, stella_deduco) VALUES ('df9b:c04d:ef2e:9db4:fb4f:2fae:ec36:ce3a/24', NULL, -713345, NULL, 46374.33, 29363.37, 'ddd3:a68f:da9c:4cac:e1d2:4dfa:c056:e51e', 'Sui curvo cognomen ullus tunc.', '2024-03-06T00:59:32.977Z', 69, '29:6e:89:f1:c0:12');
INSERT INTO ducimus_textus_433 (currus_peccatus_adopto, abundans_ab, combibo, alii, amaritudo, appono_clam, uxor_occaecati, tergum_surgo, amo_animus_paens, audax_antea_139_id, stella_deduco) VALUES ('bfde:df3a:adb3:6a0a:bfad:dc96:28b6:ddba/24', 49169.7, -526312, 'Tunc spiritus apud sit toties audacia vel.', 59647.51, 85256.11, 'f261:f469:2ce3:3f10:ff3b:0d20:430d:baf5', 'Atque decor aestivus ullus vaco vulpes curvo.', '2024-08-30T17:37:41.708Z', 83, 'c4:3b:7c:b5:bc:f3');
INSERT INTO ducimus_textus_433 (currus_peccatus_adopto, abundans_ab, combibo, alii, amaritudo, appono_clam, uxor_occaecati, tergum_surgo, amo_animus_paens, audax_antea_139_id, stella_deduco) VALUES ('253.215.62.184/24', 91377.89, -820723, 'Vindico viridis aptus deludo viridis victus adiuvo.', 9117.04, 27088.06, '12.135.73.66', 'Verecundia nulla pauper vulnero curto vomica dens degusto caveo.', '2025-06-20T14:39:04.204Z', 92, '60:23:09:4e:1f:55');
INSERT INTO ducimus_textus_433 (currus_peccatus_adopto, abundans_ab, combibo, alii, amaritudo, appono_clam, uxor_occaecati, tergum_surgo, amo_animus_paens, audax_antea_139_id, stella_deduco) VALUES ('9fb4:0e03:e9b4:de73:372b:ddde:fe97:8f0f/24', 65129.49, -262837, 'Autem tyrannus deputo vester itaque voluntarius calcar appono aufero centum.', 28362.61, 3452.22, '212.110.218.83', 'Depraedor caelestis amiculum demum arma speculum.', '2025-10-10T03:00:42.165Z', 5, 'bd:92:d1:ca:11:54');
INSERT INTO ducimus_textus_433 (currus_peccatus_adopto, abundans_ab, combibo, alii, amaritudo, appono_clam, uxor_occaecati, tergum_surgo, amo_animus_paens, audax_antea_139_id, stella_deduco) VALUES ('47.206.37.60/24', 53897.94, 641704, 'Temperantia stipes curo patruus debitis quasi solutio circumvenio.', 18249.44, 57749.71, '3.199.168.12', 'Umbra barba varietas audio demonstro absens vulgus quis.', '2025-07-01T09:41:16.715Z', 18, '1d:f3:b2:f6:ce:2e');
INSERT INTO ducimus_textus_433 (currus_peccatus_adopto, abundans_ab, combibo, alii, amaritudo, appono_clam, uxor_occaecati, tergum_surgo, amo_animus_paens, audax_antea_139_id, stella_deduco) VALUES ('94.105.241.65/24', 78196.57, 320204, 'Cruentus officia taceo stabilis cunae vos earum tabernus volo.', 82807.72, 67025.51, '194.139.117.92', 'Inflammatio casus abundans.', '2024-01-25T00:11:49.142Z', 72, '0f:75:7e:9b:75:ee');
INSERT INTO ducimus_textus_433 (currus_peccatus_adopto, abundans_ab, combibo, alii, amaritudo, appono_clam, uxor_occaecati, tergum_surgo, amo_animus_paens, audax_antea_139_id, stella_deduco) VALUES ('83c0:6bbd:f1d3:4cf6:00ad:1f6f:15ea:bdcb/24', 88017.02, -839953, 'Ademptio virga capitulus.', 14416.89, 73973.19, '84.126.85.45', 'Cena cervus curis convoco verecundia aliquam cubitum cornu antiquus.', '2025-05-15T06:19:39.088Z', 89, '35:d6:30:68:17:19');
INSERT INTO ducimus_textus_433 (currus_peccatus_adopto, abundans_ab, combibo, alii, amaritudo, appono_clam, uxor_occaecati, tergum_surgo, amo_animus_paens, audax_antea_139_id, stella_deduco) VALUES ('145.145.13.105/24', 85726.88, 985141, 'Barba depromo trado strenuus valens vitiosus comis.', 47170.82, 32038.32, NULL, 'Eligendi eos ventito terminatio defungo tego hic.', '2023-03-07T07:08:36.476Z', 92, 'f8:59:0d:58:44:ed');
INSERT INTO ducimus_textus_433 (currus_peccatus_adopto, abundans_ab, combibo, alii, amaritudo, appono_clam, uxor_occaecati, tergum_surgo, amo_animus_paens, audax_antea_139_id, stella_deduco) VALUES ('157.13.134.221/24', 65593.38, 174561, 'Torqueo canonicus impedit curvo talus ulciscor.', 32009.2, 43953.52, 'f4e4:979f:a445:96b2:b9cc:85db:854f:27a1', 'Adiuvo ars contra debitis deleo delego quisquam decens conitor.', NULL, 23, 'c4:99:c2:cf:d6:09');
INSERT INTO ducimus_textus_433 (currus_peccatus_adopto, abundans_ab, combibo, alii, amaritudo, appono_clam, uxor_occaecati, tergum_surgo, amo_animus_paens, audax_antea_139_id, stella_deduco) VALUES ('ba14:ba9c:99dd:9ffc:e7a0:adbe:6c79:67cd/24', 37697.86, -978894, 'Beatus claustrum tergeo tumultus thalassinus clibanus summa.', 65434.87, 96342.16, 'e856:2e90:cfaf:9abd:55ca:a49c:0895:f2d7', NULL, '2025-12-13T21:57:29.026Z', 52, '93:dc:4c:ae:26:4b');
INSERT INTO ducimus_textus_433 (currus_peccatus_adopto, abundans_ab, combibo, alii, amaritudo, appono_clam, uxor_occaecati, tergum_surgo, amo_animus_paens, audax_antea_139_id, stella_deduco) VALUES ('239.168.167.236/24', 35064.52, 731009, 'Quod aequitas tenax velociter colligo curto eligendi.', 7583.78, 78876.69, '57.50.75.65', 'Desipio cresco fugiat tenetur tubineus combibo.', '2025-12-18T06:33:41.524Z', 4, '7d:78:3d:40:ea:e0');
INSERT INTO ducimus_textus_433 (currus_peccatus_adopto, abundans_ab, combibo, alii, amaritudo, appono_clam, uxor_occaecati, tergum_surgo, amo_animus_paens, audax_antea_139_id, stella_deduco) VALUES ('f9de:cfe9:5e01:e738:6d8a:0cbb:3d9f:dad8/24', 79986.35, 15627, 'Et dolores ascisco verus venustas cornu suscipio.', 53569.77, 34141.39, '81.54.19.68', 'At constans cibo spiritus spiritus.', '2024-09-27T22:24:01.764Z', 48, 'bb:a0:99:cb:27:ca');
INSERT INTO ducimus_textus_433 (currus_peccatus_adopto, abundans_ab, combibo, alii, amaritudo, appono_clam, uxor_occaecati, tergum_surgo, amo_animus_paens, audax_antea_139_id, stella_deduco) VALUES ('57e7:ec5f:fa59:9e4b:b4cd:98fd:aab6:e5b4/24', 76808.85, -447005, 'Sollicito recusandae talis adipiscor perferendis fugit cotidie centum.', 78220.16, 86017.39, '093f:d3be:cf24:c0d4:9d3a:debd:d9d8:4bd8', 'Conscendo aeneus aptus atque clarus.', '2024-07-25T08:01:54.341Z', 46, '3a:e2:49:42:8e:e9');
INSERT INTO ducimus_textus_433 (currus_peccatus_adopto, abundans_ab, combibo, alii, amaritudo, appono_clam, uxor_occaecati, tergum_surgo, amo_animus_paens, audax_antea_139_id, stella_deduco) VALUES ('199.33.242.221/24', 54721.02, 137256, 'Ultra pecco validus vesica texo vel comburo.', 26123.37, 93461.12, '64.176.182.80', 'Optio sed acies crustulum adsidue alias acerbitas aegrus advoco.', '2024-09-24T19:37:53.295Z', 79, 'ad:43:7e:59:16:d2');
INSERT INTO ducimus_textus_433 (currus_peccatus_adopto, abundans_ab, combibo, alii, amaritudo, appono_clam, uxor_occaecati, tergum_surgo, amo_animus_paens, audax_antea_139_id, stella_deduco) VALUES ('14.142.219.99/24', 90665.54, NULL, 'Doloremque autem contabesco tametsi abutor.', 75894.76, 37644.67, '243.12.62.142', 'Ademptio spero ustulo stipes attollo.', '2025-11-28T21:00:52.864Z', 11, 'f6:58:25:f6:34:a6');
INSERT INTO ducimus_textus_433 (currus_peccatus_adopto, abundans_ab, combibo, alii, amaritudo, appono_clam, uxor_occaecati, tergum_surgo, amo_animus_paens, audax_antea_139_id, stella_deduco) VALUES ('7eb5:7ad8:fe9e:7b31:53e2:31fd:5cce:578c/24', 3610.42, -595779, 'Considero vorago chirographum ver optio tabgo usus auctor.', 14746.14, 13610.48, '235.41.228.237', 'Ademptio vulticulus aetas consectetur auctor aeger tamdiu ocer amplexus.', '2024-05-28T13:09:20.823Z', 41, '7c:a9:16:cc:8f:47');
INSERT INTO ducimus_textus_433 (currus_peccatus_adopto, abundans_ab, combibo, alii, amaritudo, appono_clam, uxor_occaecati, tergum_surgo, amo_animus_paens, audax_antea_139_id, stella_deduco) VALUES ('ada7:1d9d:b1c8:c387:45e0:1ddd:4344:b9ce/24', 75034.84, -395867, 'Aegrus tollo vulpes adicio tergum.', 4432.34, 29630.95, 'c307:f5b8:f9fe:faab:7fe5:931b:2bdc:a322', 'Demum repudiandae ipsam paulatim caecus carpo.', '2024-07-04T13:00:43.578Z', 46, '03:d6:d7:38:99:dc');
INSERT INTO ducimus_textus_433 (currus_peccatus_adopto, abundans_ab, combibo, alii, amaritudo, appono_clam, uxor_occaecati, tergum_surgo, amo_animus_paens, audax_antea_139_id, stella_deduco) VALUES ('169.82.166.136/24', 53987.78, -780744, 'Valens thorax accusantium adduco valeo.', 53550.18, 93884.06, '99.79.109.155', 'Taceo stultus ipsam denuo vitium usus capto repellat.', '2025-12-16T12:15:11.867Z', 25, '24:af:db:ce:aa:7f');
INSERT INTO ducimus_textus_433 (currus_peccatus_adopto, abundans_ab, combibo, alii, amaritudo, appono_clam, uxor_occaecati, tergum_surgo, amo_animus_paens, audax_antea_139_id, stella_deduco) VALUES ('ad98:4c1e:d82a:b284:516a:d70f:c79d:cffc/24', 85247.53, -829753, 'Una praesentium aestus valde soluta vapulus paulatim sublime cupiditate.', 58366.2, 64993, 'a3e9:e91f:5e54:cca6:2da0:03c5:8953:35ed', 'Tamen adduco decumbo excepturi cultellus auxilium vicissitudo.', '2023-07-08T10:11:34.202Z', 3, '05:eb:bd:a2:60:46');
INSERT INTO ducimus_textus_433 (currus_peccatus_adopto, abundans_ab, combibo, alii, amaritudo, appono_clam, uxor_occaecati, tergum_surgo, amo_animus_paens, audax_antea_139_id, stella_deduco) VALUES ('62.30.57.62/24', 26817.66, 254099, 'Dolor vis adversus tubineus curia pecco sub adsuesco tenus.', 51911.59, 78229.13, '74.95.193.6', 'Desolo adipiscor thymbra vestrum ventosus tam incidunt quasi demum sopor.', '2023-05-01T22:23:26.454Z', 1, '5d:fa:2c:5a:6d:ae');
INSERT INTO ducimus_textus_433 (currus_peccatus_adopto, abundans_ab, combibo, alii, amaritudo, appono_clam, uxor_occaecati, tergum_surgo, amo_animus_paens, audax_antea_139_id, stella_deduco) VALUES ('129.231.37.227/24', 87612.83, -608598, 'Vesco decens arto ipsum inflammatio incidunt sapiente altus.', 69209.2, 1085.68, '78.206.87.180', 'Ubi cura sequi decor communis compello.', '2025-11-22T19:00:23.925Z', 98, '1a:88:93:24:7e:2a');
INSERT INTO ducimus_textus_433 (currus_peccatus_adopto, abundans_ab, combibo, alii, amaritudo, appono_clam, uxor_occaecati, tergum_surgo, amo_animus_paens, audax_antea_139_id, stella_deduco) VALUES ('9870:9df6:3dbf:cdae:2bcf:a5be:9baf:47e7/24', 68763.04, 350494, 'Contego umquam aegrotatio utor vita suffoco.', 80068.46, 1594.34, '196.249.25.240', NULL, '2024-12-23T08:07:44.921Z', 100, 'eb:6c:1f:25:11:65');
INSERT INTO ducimus_textus_433 (currus_peccatus_adopto, abundans_ab, combibo, alii, amaritudo, appono_clam, uxor_occaecati, tergum_surgo, amo_animus_paens, audax_antea_139_id, stella_deduco) VALUES ('4fd3:1f1e:1ed7:bb5e:3f69:3353:79bc:b5ce/24', 65763.19, 495109, 'Alienus appello deporto ea vinitor.', 11439.36, 80585.41, 'b90c:3b55:a31f:af47:5148:fdf8:eab6:a8fe', 'Curso decimus tabgo auxilium porro ipsum adhuc tabesco doloremque illum.', '2023-12-05T05:11:30.701Z', 25, '51:0a:9e:91:23:05');
INSERT INTO ducimus_textus_433 (currus_peccatus_adopto, abundans_ab, combibo, alii, amaritudo, appono_clam, uxor_occaecati, tergum_surgo, amo_animus_paens, audax_antea_139_id, stella_deduco) VALUES ('9d1e:05e7:85d8:6ec8:c0e9:ade6:ad7d:45ba/24', 80970.1, -805336, NULL, 5397.15, 86876, '68.206.113.90', 'Fugiat agnitio cibo stabilis theca umerus curto censura.', '2024-08-09T08:02:01.457Z', 51, 'bb:13:7d:39:ef:07');
INSERT INTO ducimus_textus_433 (currus_peccatus_adopto, abundans_ab, combibo, alii, amaritudo, appono_clam, uxor_occaecati, tergum_surgo, amo_animus_paens, audax_antea_139_id, stella_deduco) VALUES ('ff5e:ea69:d3ac:4eb8:bf1b:d5f7:eb0f:55af/24', 60047.81, 314071, 'Bellicus bellum tardus bibo dedico.', 91191.91, 3981.94, '110.100.138.179', 'Clam adsum cauda beatus.', '2024-11-07T15:32:39.855Z', 80, '84:de:24:5a:56:26');
INSERT INTO ducimus_textus_433 (currus_peccatus_adopto, abundans_ab, combibo, alii, amaritudo, appono_clam, uxor_occaecati, tergum_surgo, amo_animus_paens, audax_antea_139_id, stella_deduco) VALUES ('87a5:c00b:fdcd:cbd0:bfee:08f1:f999:fcad/24', 42490.59, 563237, 'Patruus trans at asporto aegrus dolore callide derelinquo.', 77305.63, 49100.69, 'bafd:d36a:c322:8ce1:19fd:4a6d:b7df:bfa8', 'Amplexus vox creator adipiscor.', '2024-02-11T05:06:10.337Z', 93, '77:87:dc:e2:09:43');
INSERT INTO ducimus_textus_433 (currus_peccatus_adopto, abundans_ab, combibo, alii, amaritudo, appono_clam, uxor_occaecati, tergum_surgo, amo_animus_paens, audax_antea_139_id, stella_deduco) VALUES ('b732:ea02:9af5:c2ed:0c1e:0dfc:e7f1:2ba7/24', 50125.86, 990038, 'Deduco aveho sapiente vergo perferendis cunabula corrumpo arx aestas.', 14079.76, 39396.81, '247.141.26.83', 'Quasi tenetur cilicium iste ex vulgaris tremo spiculum.', '2024-12-13T06:36:48.094Z', 78, '8e:be:11:e5:dc:64');
INSERT INTO celer_bellicus_765 (uxor_repudiandae_cresco, ipsam_labore, defendo_peccatus_vehemens, cibo, quod, caput, ad_advoco, cupiditas_tamen_culpo, asperiores_barba, deficio, textus_cena, tubineus_tempora, admoneo_conduco, suspendo, repudiandae_at_statua) VALUES (NULL, NULL, 'a5:9f:ea:a5:c1:db', ARRAY[1,94,23], '\xfalse7B927D68dACEdDfe', '2023-04-19T08:19:48.768Z', '{"key":"thorax","value":48}', 61674.59, 34056.09, '2023-04-12T08:58:14.181Z', 82048.34, '2025-04-17T13:56:53.980Z', '\xfalse2af998DA40DFFC38', '\xfalseADDB79c839C2D826', '2024-11-12');
