INSERT INTO bardus_sumo_809 (adduco_aegrus, angustus_termes, verus_facere_dolorem, antepono_desolo, tumultus_cornu_temptatio, vulticulus, architecto_terreo, pecus_creta_desolo) VALUES (false, '2023-12-09T15:17:00.830Z', false, '{"key":"creptio","value":10}', '{"key":"molestiae","value":81}', 'Aegrus demitto illo barba valeo suggero suus denique assentator blandior.', '2024-03-18T14:19:23.270Z', '185.152.159.105');
INSERT INTO bardus_sumo_809 (adduco_aegrus, angustus_termes, verus_facere_dolorem, antepono_desolo, tumultus_cornu_temptatio, vulticulus, architecto_terreo, pecus_creta_desolo) VALUES (false, '2025-10-09T13:45:22.548Z', true, '{"key":"similique","value":29}', '{"key":"sodalitas","value":77}', 'Bene enim umquam complectus depereo sequi.', '2023-08-10T18:21:06.515Z', 'd9dc:acde:d276:233c:c2eb:ed3f:665f:9daa');
INSERT INTO bardus_sumo_809 (adduco_aegrus, angustus_termes, verus_facere_dolorem, antepono_desolo, tumultus_cornu_temptatio, vulticulus, architecto_terreo, pecus_creta_desolo) VALUES (true, '2025-01-05T02:55:02.706Z', false, '{"key":"consequuntur","value":64}', '{"key":"perspiciatis","value":69}', 'Ultio valetudo ambulo sumptus adsidue comitatus.', '2024-01-20T08:40:04.579Z', '224.218.184.150');
INSERT INTO bardus_sumo_809 (adduco_aegrus, angustus_termes, verus_facere_dolorem, antepono_desolo, tumultus_cornu_temptatio, vulticulus, architecto_terreo, pecus_creta_desolo) VALUES (true, '2025-03-02T10:59:41.279Z', true, '{"key":"contabesco","value":42}', '{"key":"beneficium","value":89}', NULL, '2023-05-18T11:07:09.316Z', 'c663:def8:e0f7:f148:827f:1001:d1e2:a1fc');
