INSERT INTO bardus_sumo_809 (adduco_aegrus, angustus_termes, verus_facere_dolorem, antepono_desolo, tumultus_cornu_temptatio, vulticulus, architecto_terreo, pecus_creta_desolo) VALUES (false, '2023-08-19T01:30:05.800Z', true, '{"key":"cicuta","value":88}', '{"key":"thesis","value":57}', 'Eum combibo cubo bellicus tamdiu vociferor inflammatio commodo decet.', '2023-12-23T10:54:29.993Z', '246.180.26.80');
INSERT INTO bardus_sumo_809 (adduco_aegrus, angustus_termes, verus_facere_dolorem, antepono_desolo, tumultus_cornu_temptatio, vulticulus, architecto_terreo, pecus_creta_desolo) VALUES (false, '2025-08-08T02:21:30.504Z', false, '{"key":"suffragium","value":54}', NULL, 'Aperte blanditiis quas creber antepono.', '2024-08-11T08:04:47.432Z', '236.221.88.7');
INSERT INTO bardus_sumo_809 (adduco_aegrus, angustus_termes, verus_facere_dolorem, antepono_desolo, tumultus_cornu_temptatio, vulticulus, architecto_terreo, pecus_creta_desolo) VALUES (false, '2025-01-08T01:05:20.511Z', false, '{"key":"laborum","value":62}', '{"key":"alioqui","value":30}', 'Claudeo confido expedita avaritia esse censura utrimque antea abduco atqui.', '2023-05-26T03:56:17.227Z', '14e3:f4e2:8b2b:128f:b17a:e272:da9e:5dff');
INSERT INTO bardus_sumo_809 (adduco_aegrus, angustus_termes, verus_facere_dolorem, antepono_desolo, tumultus_cornu_temptatio, vulticulus, architecto_terreo, pecus_creta_desolo) VALUES (true, '2024-10-05T23:23:07.290Z', true, '{"key":"nihil","value":41}', '{"key":"cupiditas","value":45}', 'Quasi vociferor apud asporto adversus.', NULL, '136.84.237.197');
INSERT INTO bardus_sumo_809 (adduco_aegrus, angustus_termes, verus_facere_dolorem, antepono_desolo, tumultus_cornu_temptatio, vulticulus, architecto_terreo, pecus_creta_desolo) VALUES (false, '2025-08-20T18:04:01.434Z', true, '{"key":"addo","value":96}', '{"key":"absum","value":20}', 'Pax officiis aqua aqua ustulo pecco dapifer color tabernus arguo.', '2023-04-17T09:40:30.139Z', '149.111.192.178');
INSERT INTO bardus_sumo_809 (adduco_aegrus, angustus_termes, verus_facere_dolorem, antepono_desolo, tumultus_cornu_temptatio, vulticulus, architecto_terreo, pecus_creta_desolo) VALUES (true, '2026-01-17T03:04:28.944Z', true, NULL, '{"key":"varius","value":18}', 'Adimpleo ventosus cum suppellex tutis spoliatio.', '2023-09-24T09:30:46.829Z', 'ac2b:cf7d:34ae:dd7f:f21e:c470:9ced:acea');
