INSERT INTO artificiose_solum_870 (esse_conatus, cruentus_vobis, tamdiu_ventosus_abeo, demergo, cruciamentum_vox, volo_depraedor_subito, tamen_catena_utique, infit_creber_tollo, urbanus, tendo_templum, considero_vulnus_dapifer, adnuo, ceno, celo, nisi_laudantium_561_id) VALUES (NULL, 46681.07, 'Depopulo vorax conatus sui trepide aliquid adeo venia bardus.', 'Vaco alius labore caveo perferendis summopere crebro.', 955, -8736, '87890c11-dfee-4080-8e29-dcc084af45e9', 12202.83, '2023-06-27T10:16:08.754Z', '{"key":"debitis","value":73}', 'Tollo civis beatae audeo sulum deleniti delectus.', 37400.33, 89585.54, 'Utrum eius cogo debitis.', 52);
INSERT INTO artificiose_solum_870 (esse_conatus, cruentus_vobis, tamdiu_ventosus_abeo, demergo, cruciamentum_vox, volo_depraedor_subito, tamen_catena_utique, infit_creber_tollo, urbanus, tendo_templum, considero_vulnus_dapifer, adnuo, ceno, celo, nisi_laudantium_561_id) VALUES (ARRAY['ventito','attonbitus','sumo'], 58148.06, 'Vitiosus aufero ustulo vacuus vinitor infit umquam pecto velum.', 'Amaritudo rerum vulnero coepi pectus inflammatio sperno barba.', -226, 5306, 'e4f1f0e4-8666-43b9-9f3c-815133b71640', 22061.12, '2025-01-21T20:22:36.741Z', '{"key":"doloribus","value":96}', 'Ait turpis appositus demitto cicuta defaeco corrigo absens magnam.', 29195.58, 2811.44, 'Delicate barba ustilo delicate uter amoveo cultura.', 1);
INSERT INTO artificiose_solum_870 (esse_conatus, cruentus_vobis, tamdiu_ventosus_abeo, demergo, cruciamentum_vox, volo_depraedor_subito, tamen_catena_utique, infit_creber_tollo, urbanus, tendo_templum, considero_vulnus_dapifer, adnuo, ceno, celo, nisi_laudantium_561_id) VALUES (ARRAY['tactus','repudiandae','conforto'], 7524.63, 'Deserunt coma benigne circumvenio cervus tutis arto bellum velut vigor.', 'Molestias denego stips atavus censura debeo verbera tenetur.', NULL, 7098, '3807eecb-6c1b-4355-b9cb-8cf73c61ea24', 16881.03, '2023-07-10T11:16:52.287Z', '{"key":"super","value":30}', 'Subseco animus cupio atqui arcesso perferendis acies inflammatio vae dignissimos.', 35524.6, 46953.28, 'Vigor cur denuncio facere spes aestivus.', 66);
INSERT INTO artificiose_solum_870 (esse_conatus, cruentus_vobis, tamdiu_ventosus_abeo, demergo, cruciamentum_vox, volo_depraedor_subito, tamen_catena_utique, infit_creber_tollo, urbanus, tendo_templum, considero_vulnus_dapifer, adnuo, ceno, celo, nisi_laudantium_561_id) VALUES (ARRAY['vado','amor','eos'], 37438.27, 'Defluo nam tergiversatio tendo acidus.', 'Decet certe chirographum usus certus.', 288, 5584, '2161d10d-70a7-4fe7-b8ea-47ff7ec81e9b', 51806.69, '2025-08-16T06:32:54.255Z', '{"key":"varietas","value":79}', 'Delectatio clementia cruentus vester tametsi deficio absque soluta.', 62098.84, 11369.12, 'Cognatus altus crudelis.', 39);
INSERT INTO artificiose_solum_870 (esse_conatus, cruentus_vobis, tamdiu_ventosus_abeo, demergo, cruciamentum_vox, volo_depraedor_subito, tamen_catena_utique, infit_creber_tollo, urbanus, tendo_templum, considero_vulnus_dapifer, adnuo, ceno, celo, nisi_laudantium_561_id) VALUES (ARRAY['defero','substantia','coniecto'], 71768.11, 'Appono calamitas correptius aestivus deleo ancilla quo.', 'Sulum velut blanditiis comis corpus conscendo ipsam contra infit.', 1375, 3351, '7d82ccf2-f2a2-4a71-a568-0dac70b90ff7', 56999.94, '2026-02-01T14:07:34.797Z', '{"key":"suppellex","value":21}', 'Auctor tenetur voluptatem peccatus vigilo uterque apparatus adipisci tumultus.', NULL, 38381.59, 'Ante acceptus porro aggredior deorsum cetera tersus valeo comminor.', 66);
INSERT INTO artificiose_solum_870 (esse_conatus, cruentus_vobis, tamdiu_ventosus_abeo, demergo, cruciamentum_vox, volo_depraedor_subito, tamen_catena_utique, infit_creber_tollo, urbanus, tendo_templum, considero_vulnus_dapifer, adnuo, ceno, celo, nisi_laudantium_561_id) VALUES (ARRAY['statua','appositus','balbus'], 27599.45, 'Celer conatus thesis compello defaeco tenetur stipes.', 'Trado tendo arceo tempus deripio cresco paens adiuvo.', 9726, 7998, 'bcaf46bb-c26c-43b0-a6ba-7f4007221d58', 11700.19, '2026-01-06T05:32:07.978Z', '{"key":"corpus","value":45}', 'Rem viscus accusamus iusto carmen iusto tam aequitas aperte adnuo.', 97156.55, 56648.76, 'Audacia spargo decimus comedo.', 47);
