INSERT INTO tabella_pel_170 (vox, suadeo_textor_cauda, amplus_terminatio, cibus_calcar, aufero_theatrum_voco, communis, denego_vociferor, consectetur_ter, uredo_utrimque_terra, vomer, spectaculum_claro_depraedor, calculus, quisquam_verus, arceo) VALUES ('Virga solio convoco asper modi tripudio aspicio venio audacia.', '242be12e-ada1-42db-a3c5-d0f74e531022', '\xfalsece9FeaBFE2EdAad6', 'b0be:feda:b5ef:e8bf:bbec:c8b0:be70:d576', '\xfalseFBCf30D9F32B0aC7', 'Caput peior dedecor denego amet.', false, 11020.35, '2025-07-13', 29555.3, -5268, 'Sursum comis vicissitudo suppono cupio tamdiu.', -816562, 'Textus tempora combibo dolore crur approbo combibo administratio adhuc.');
INSERT INTO tabella_pel_170 (vox, suadeo_textor_cauda, amplus_terminatio, cibus_calcar, aufero_theatrum_voco, communis, denego_vociferor, consectetur_ter, uredo_utrimque_terra, vomer, spectaculum_claro_depraedor, calculus, quisquam_verus, arceo) VALUES ('Cubicularis calcar quasi veritas velociter sunt arbitro ceno.', 'ded50028-113d-4cc3-bccc-d84f7b353268', '\xfalse4dd7b7d9FE75af0D', '9a8a:cbe4:a82a:2aab:7eca:0f96:f25b:fccd', '\xfalseD77CcbbebcEceeB8', 'Deleniti congregatio amplitudo.', false, 84661, '2024-05-05', 57658.92, 8018, 'Aequitas defluo utrimque carcer textus voro certe adversus.', 535473, 'Agnosco usitas thermae usque cunae arcus labore.');
INSERT INTO tabella_pel_170 (vox, suadeo_textor_cauda, amplus_terminatio, cibus_calcar, aufero_theatrum_voco, communis, denego_vociferor, consectetur_ter, uredo_utrimque_terra, vomer, spectaculum_claro_depraedor, calculus, quisquam_verus, arceo) VALUES (NULL, 'a8ad39fc-ee69-4616-b1b3-10825d9f0616', '\xfalseCEfed56cBBDaD5fa', '68d0:e84a:fa78:e9e0:4bfe:b9ff:bcb3:abad', '\xfalseB6DCc4dca0dFA9BB', 'Solutio autem videlicet minima amaritudo vitium super adipiscor cura.', false, 94808.2, '2023-09-05', 45862.58, -817, 'Tabula vinitor triumphus acidus reprehenderit vigilo similique desino solum.', 800632, 'Nostrum defleo creber contigo error abundans paens.');
INSERT INTO tabella_pel_170 (vox, suadeo_textor_cauda, amplus_terminatio, cibus_calcar, aufero_theatrum_voco, communis, denego_vociferor, consectetur_ter, uredo_utrimque_terra, vomer, spectaculum_claro_depraedor, calculus, quisquam_verus, arceo) VALUES (NULL, '53cfaf4c-efba-4c27-8a33-b991b0ab445e', '\xfalse5DEAd0a0e5b55a45', '34.231.216.208', '\xfalseaCb3F082befDb0cd', 'Tribuo convoco cupiditas.', false, NULL, '2023-04-17', 18740.03, 6996, 'Ea accusator tumultus confero vomica maxime tamdiu sollers sursum.', -859531, 'Sint correptius stillicidium damno aegrus tolero atavus creta clibanus charisma.');
INSERT INTO tabella_pel_170 (vox, suadeo_textor_cauda, amplus_terminatio, cibus_calcar, aufero_theatrum_voco, communis, denego_vociferor, consectetur_ter, uredo_utrimque_terra, vomer, spectaculum_claro_depraedor, calculus, quisquam_verus, arceo) VALUES ('Adulatio viridis bibo alioqui ipsa eius.', 'b432479f-a7cb-4275-9ab7-492a018f9002', '\xfalse80Cea4D2AeECF9Fd', '14ec:b209:5c34:9caa:9d26:1e65:f2c2:737a', '\xfalse387e3680804a5ADe', 'Ullam vallum curatio.', false, 50760.28, '2024-09-18', 3473.55, -9594, 'Aureus caterva clementia aperio adeo abeo calco.', 930020, 'Auditor tergeo assentator talis cribro minus atrocitas.');
INSERT INTO tabella_pel_170 (vox, suadeo_textor_cauda, amplus_terminatio, cibus_calcar, aufero_theatrum_voco, communis, denego_vociferor, consectetur_ter, uredo_utrimque_terra, vomer, spectaculum_claro_depraedor, calculus, quisquam_verus, arceo) VALUES (NULL, 'f9bd8dab-2c44-4b2e-9693-d40e040cdb4a', '\xfalsef2E68a8e9b8b55B1', 'cfa1:671c:dcf1:5fea:d4db:3b6d:2c1b:b37e', '\xfalse6f597EcfE32D3ddd', 'Adimpleo decretum vaco odit theca amicitia celo temptatio.', true, 42497.5, '2024-10-20', 32600.52, 9651, 'Sopor tribuo textor color contra crepusculum.', -248258, 'Valde demitto alius claro dapifer sint conforto amplexus solvo.');
INSERT INTO tabella_pel_170 (vox, suadeo_textor_cauda, amplus_terminatio, cibus_calcar, aufero_theatrum_voco, communis, denego_vociferor, consectetur_ter, uredo_utrimque_terra, vomer, spectaculum_claro_depraedor, calculus, quisquam_verus, arceo) VALUES ('Iusto vilicus caelestis corroboro tepidus.', 'e2100450-1578-44f7-aba2-4da10e226621', '\xfalsedfBA206c3ffdc642', '6e8a:beb0:f4c3:3d3a:dcd8:4088:1d8a:dfff', '\xfalse84A6c53F9E93A7E6', 'Abeo quisquam denuncio debilito maiores acies.', false, 30130.79, '2025-05-01', 31517.13, -3137, 'Coadunatio admiratio defungo attonbitus.', 643784, 'Crepusculum condico ter creptio summisse articulus unde nam fugiat.');
INSERT INTO tabella_pel_170 (vox, suadeo_textor_cauda, amplus_terminatio, cibus_calcar, aufero_theatrum_voco, communis, denego_vociferor, consectetur_ter, uredo_utrimque_terra, vomer, spectaculum_claro_depraedor, calculus, quisquam_verus, arceo) VALUES ('Sursum tenuis unus conturbo at conscendo vilis ter curia.', '3edccca0-8375-4585-9f0e-9716234482fe', '\xfalseda96a3F39Ef555ac', '1de7:bdb2:b1c1:db7b:8fa5:829a:05ab:cf62', '\xfalseC9BF3cc6defcC9Bd', 'Auditor pax territo ago adhaero cursus vacuus audentia.', false, NULL, '2025-07-30', 60589.24, 1775, 'Delibero censura calco anser vulgo cetera agnosco similique statua vigilo.', -698551, 'Dedico capitulus suppellex harum hic adflicto accedo.');
INSERT INTO tabella_pel_170 (vox, suadeo_textor_cauda, amplus_terminatio, cibus_calcar, aufero_theatrum_voco, communis, denego_vociferor, consectetur_ter, uredo_utrimque_terra, vomer, spectaculum_claro_depraedor, calculus, quisquam_verus, arceo) VALUES ('Caute armarium tabula trans ullam vobis thalassinus considero.', '58c2a0fa-4ef5-4036-851b-4433aa7cd16e', '\xfalsefBF49Ef4F3EBeC10', '162f:a8f0:dc0c:1c34:3d2a:ccc5:cc7e:7ba8', '\xfalsefe2aDcA42faf4cA2', 'Dapifer asporto utor aequus abutor.', true, 39250.1, '2023-03-13', 39027.15, -6916, 'Tenus absorbeo verbera tutamen convoco velum claudeo.', 680002, 'Adduco triumphus conicio adipiscor sophismata cuius.');
INSERT INTO tabella_pel_170 (vox, suadeo_textor_cauda, amplus_terminatio, cibus_calcar, aufero_theatrum_voco, communis, denego_vociferor, consectetur_ter, uredo_utrimque_terra, vomer, spectaculum_claro_depraedor, calculus, quisquam_verus, arceo) VALUES ('Depopulo acceptus sapiente timidus thymum depraedor apto apostolus.', '8be702b4-70e1-40e6-8a8f-8c8a1d05d07b', '\xfalsee2eA62E3bDa2d4d1', '229.161.43.3', '\xfalse5D8CcB451e6be2BD', 'Pauper spes tonsor tenuis sollicito avarus.', false, 18339.29, '2023-12-22', 91226.1, -2467, 'Vestigium volutabrum deserunt tenetur stultus blanditiis.', 202898, 'Ea quod et toties.');
